27	
28	 public:
29	  /**
30	   * 默认构造一个shape，默认构造的shape实例中，dim_num长度为0
31	   */
32	  Shape() : dim_num_(0), dims_{0} {
33	    (void)memset(reserved_, 0, sizeof(reserved_));  // memset函数misra告警屏蔽
34	  }
35	
36	  /**
37	   * 通过dims值构造shape，例如：Shape({8,3,224,224})创建一个Shape实例，有4个维度，每个维度的值分别是8,3,224,224
38	   * @param dims shape的所有dim值
39	   */
40	  Shape(const std::initializer_list<int64_t> &args) : Shape() {
41	    if (args.size() > kMaxDimNum) {
42	      return;
43	    }
44	    dim_num_ = args.size();
45	    size_t i = 0;
46	    for (const int64_t arg : args) {
47	      dims_[i++] = arg;
48	    }
49	  }
50	
51	  /**
52	   * 拷贝构造
53	   * @param other 源对象
54	   * 为了提升性能，dims_超过dim_num_的空间没有拷贝，可能有脏数据
55	   */
56	  Shape(const Shape &other) {
57	    dim_num_ = other.dim_num_;
58	    for (size_t i = 0U; i < dim_num_; ++i) {
59	      dims_[i] = other.dims_[i];
60	    }
61	    (void)memset(reserved_, 0, sizeof(reserved_));  // memset函数misra告警屏蔽
62	  }
63	
64	  /**
65	   * 拷贝赋值
66	   * @param other
67	   * @return
68	   * 为了提升性能，dims_超过dim_num_的空间没有拷贝，可能有脏数据
69	   */
70	  Shape &operator=(const Shape &other) {
71	    if (&other != this) {
72	      dim_num_ = other.dim_num_;
73	      for (size_t i = 0U; i < dim_num_; ++i) {
74	        dims_[i] = other.dims_[i];
75	      }
76	    }
77	    (void)memset(reserved_, 0, sizeof(reserved_));  // memset函数misra告警屏蔽
78	    return *this;
79	  }
80	
81	  /**
82	   * 判断与另外一个shape对象是否相等，如果两个shape的dim num并且dim num内每个dim的值都相等，那么认为两个shape相等
83	   * @param rht 另一个Shape对象
84	   * @return true/false
85	   */
86	  bool operator==(const Shape &rht) const {
87	    if (this->dim_num_ != rht.dim_num_) {
88	      return false;
89	    }
90	    for (size_t i = 0; i < this->dim_num_; i++) {
91	      if (this->dims_[i] != rht.dims_[i]) {
92	        return false;
93	      }
94	    }
95	    return true;
