107	  /**
108	   * 获取shape size，所谓shape size，是指shape中有多少个元素
109	   * @return shape-size，在发生溢出时，返回`kInvalidDimValue`
110	   */
111	  int64_t GetShapeSize() const {
112	    int64_t shape_size = 1;
113	    for (size_t i = 0; i < dim_num_; ++i) {
114	      if (ge::MulOverflow(shape_size, dims_[i], shape_size)) {
115	        return kInvalidDimValue;
116	      }
117	    }
118	    return shape_size;
119	  }
120	
121	  /**
122	   * 判断本shape是否为标量，所谓标量，是指GetDimNum()为0
123	   * @return true/false
124	   */
125	  bool IsScalar() const {
126	    return dim_num_ == 0L;
127	  }
128	
129	  /**
130	   * 设置shape为标量
131	   * @param none
132	   */
133	  void SetScalar() {
134	    dim_num_ = 0;
135	  }
136	
137	  /**
138	   * 获取dim num
139	   * @return
140	   */
141	  size_t GetDimNum() const {
142	    return dim_num_;
143	  }
144	
145	  /**
146	   * 设置dim num
147	   * @param dim_num
148	   */
149	  void SetDimNum(const size_t dim_num) {
150	    this->dim_num_ = dim_num;
151	  }
152	
153	  /**
154	   * 获取dim值
155	   * @param idx dim的index，调用者需要保证index合法
156	   * @return dim值，在idx超出MaxDimNum时，返回`kInvalidDimValue`
157	   */
158	  int64_t GetDim(const size_t idx) const {
159	    if (idx >= kMaxDimNum) {
160	      return kInvalidDimValue;
161	    }
162	    return dims_[idx];
163	  }
164	
165	  /**
166	   * 获取dim值
167	   * @param idx dim的index，调用者需要保证index合法
168	   * @return dim值，行为未定义
169	   */
170	  const int64_t &operator[](const size_t idx) const {
171	    return dims_[idx];
172	  }
173	
174	  /**
175	   * 获取dim值
176	   * @param idx dim的index，调用者需要保证index合法
177	   * @return dim值，在idx超出MaxDimNum时，行为未定义
178	   */
179	  int64_t &operator[](const size_t idx) {
180	    return dims_[idx];
181	  }
182	
183	  /**
184	   * 设置dim值
185	   * @param idx dim的index，调用者需要保证index合法
186	   * @return
187	   */
188	  void SetDim(size_t idx, const int64_t dim_value) {
189	    if (idx >= kMaxDimNum) {
190	      return;
191	    }
192	    dims_[idx] = dim_value;
193	    this->dim_num_ = (this->dim_num_ < idx) ? idx : this->dim_num_;
194	  }
195	
196	  /**
197	   * 向后扩展一个dim值，如果扩展的dim数量超出Shape的最大限制，那么本函数不做任何事情
