  TensorV2 t2 = {{}, {}, {}, {}, nullptr};
  const TensorV2 &ct = t2;
  t2.MutableOriginShape() = Shape{8, 3, 224, 224};
  t2.MutableStorageShape() = Shape{8, 1, 224, 224, 16};
